class Solution {
  public boolean isUgly(int num) {
    if (num < 1) {
      return false;
    }
    for (int f : new int[] { 2, 3, 5 }) {
      while (num % f == 0) {
        num /= f;
      }
    }
    return num == 1;
  }
}

class Solution:
    def isUgly(self, num: int) -> bool:
        if num < 1:
            return False
        for f in (2, 3, 5):
            while num % f == 0:
                num //= f
        return num == 1

impl Solution {
  pub fn is_ugly(mut num: i32) -> bool {
    if num < 1 {
      return false;
    }
    for f in [2, 3, 5] {
      while num % f == 0 {
        num /= f;
      }
    }
    num == 1
  }
}

const isUgly = (num: number): boolean => {
  if (num < 1) return false;
  for (const f of [2, 3, 5]) {
    while (num % f === 0) num /= f;
  }
  return num === 1;
};
